_FALLBACK_SRC = '# Exact action format: {"moves": [[from_node, to_node, count], ...]}\n# Payout: if player_units[i] > opponent_units[i], you earn demand[i];\n# if player_units[i] < opponent_units[i], the opponent earns demand[i];\n# if player_units[i] == opponent_units[i], nobody earns there.\n# Move cost = MOVE_COST * (sum of count over your legal moves this turn).\n# Units move at most one edge per turn; edge capacity counts both directions.\n\nfrom collections import deque\nimport time\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nMOVE_COST = 0.5\n\n\ndef node_payout(own, opponent, demand):\n    """Exact revenue for both players at one node, before movement costs."""\n    if own > opponent:\n        return demand, 0\n    if own < opponent:\n        return 0, demand\n    return 0, 0\n\n\ndef preprocess_map(obs):\n    n = int(obs["n_nodes"])\n    adjacency = [[] for _ in range(n)]\n    capacities = {}\n    for edge, capacity in zip(obs["edges"], obs["edge_capacity"]):\n        u, v = int(edge[0]), int(edge[1])\n        capacities[min(u, v), max(u, v)] = int(capacity)\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if distance[v] == -1:\n                    distance[v] = distance[u] + 1\n                    queue.append(v)\n        distances.append(distance)\n\n    return n, adjacency, capacities, distances\n\n\ndef plan_moves(obs, map_data, deadline):\n    """Keep paying holdings; use spare units only for uncontested expansion."""\n    n, adjacency, capacities, distances = map_data\n    own = obs["player_units"]\n    opponent = obs["opponent_units"]\n    demand = obs["demand"]\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    if remaining == 0:\n        return []\n\n    spare = list(own)\n    targets = []\n    for v in range(n):\n        revenue, _ = node_payout(own[v], opponent[v], demand[v])\n        if revenue > 0:\n            # Never sacrifice an existing positive revenue stream.\n            spare[v] = max(0, own[v] - opponent[v] - 1)\n        elif demand[v] > 0 and opponent[v] == 0 and own[v] == 0:\n            targets.append(v)\n\n    # Each unoccupied target needs only one unit. No reinforcements or fights.\n    # Reserve destinations within this plan so multiple origins cannot overfill.\n    candidates = []\n    for source in range(n):\n        if spare[source] <= 0:\n            continue\n        for target in targets:\n            hops = distances[source][target]\n            if hops <= 0 or hops > remaining:\n                continue\n            earning_turns = remaining - hops + 1\n            travel_cost = MOVE_COST * hops\n            # Require a generous positive margin, not merely theoretical break-even.\n            if demand[target] * earning_turns <= travel_cost + 2.0:\n                continue\n            candidates.append((hops, -demand[target], target, source))\n    candidates.sort()\n\n    reserved = set()\n    edge_left = dict(capacities)\n    planned = []\n    for hops, _, target, source in candidates:\n        if time.perf_counter() >= deadline:\n            break\n        if target in reserved or spare[source] <= 0:\n            continue\n        next_node = None\n        for neighbor in adjacency[source]:\n            edge = (min(source, neighbor), max(source, neighbor))\n            if (distances[neighbor][target] == hops - 1\n                    and edge_left[edge] > 0):\n                next_node = neighbor\n                break\n        if next_node is None:\n            continue\n        edge = (min(source, next_node), max(source, next_node))\n        spare[source] -= 1\n        edge_left[edge] -= 1\n        reserved.add(target)\n        planned.append((source, next_node, 1))\n    return planned\n\n\ndef legal_action(plan, obs, map_data):\n    """Replay against start-of-turn units, never crediting incoming units."""\n    n, _, capacities, _ = map_data\n    available = [int(x) for x in obs["player_units"]]\n    capacity_left = dict(capacities)\n    combined = {}\n    for source, target, count in plan:\n        source, target, count = int(source), int(target), int(count)\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        edge = (min(source, target), max(source, target))\n        if source == target or edge not in capacity_left or count <= 0:\n            continue\n        count = min(count, available[source], capacity_left[edge])\n        if count <= 0:\n            continue\n        available[source] -= count\n        capacity_left[edge] -= count\n        pair = (source, target)\n        combined[pair] = combined.get(pair, 0) + count\n    return {\n        "moves": [\n            [int(source), int(target), int(count)]\n            for (source, target), count in sorted(combined.items())\n        ]\n    }\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs)\n        plan = plan_moves(obs, self.map_data, deadline)\n        return legal_action(plan, obs, self.map_data)\n'
